static const z_t58_t _zag1647[] = {{ .data = "@xmalloc", .size = 8 }};

static const z_t6098_t _zag1648 = { { .data = "win_wide", .size = 8 }, { .length = 1, .data = _zag1646 }, { .length = 1, .data = _zag1647 }, { .data = "static wchar_t* z_win_wide(const char* s, size_t n) {\n    if (n > (size_t)INT_MAX) {\n        SetLastError(ERROR_FILENAME_EXCED_RANGE);\n        return NULL;\n    }\n    int wn = 0;\n    if (n > 0) {\n        wn = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, s, (int)n, NULL, 0);\n        if (wn == 0) return NULL;\n    }\n    wchar_t* w = (wchar_t*)z_xmalloc(((size_t)wn + 1) * sizeof(wchar_t));\n    if (n > 0) MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, s, (int)n, w, wn);\n    w[wn] = 0;\n    return w;\n}", .size = 509 } };
static const z_t58_t _zag1649[] = {{ .data = "@win_utf8", .size = 9 }};

static const z_t6098_t _zag1650 = { { .data = "win_utf8", .size = 8 }, { .length = 1, .data = _zag1649 }, { .length = 1, .data = _zag1647 }, { .data = "static char* z_win_utf8(const wchar_t* w, int wn, size_t* len) {\n    int n = WideCharToMultiByte(CP_UTF8, 0, w, wn, NULL, 0, NULL, NULL);\n    if (n == 0 && wn != 0) return NULL;\n    char* s = (char*)z_xmalloc((size_t)n + 1);\n    if (n > 0) WideCharToMultiByte(CP_UTF8, 0, w, wn, s, n, NULL, NULL);\n    /* a NUL-terminated source counts its terminator */\n    if (wn < 0 && n > 0) n--;\n    s[n] = '\\0';\n    if (len) *len = (size_t)n;\n    return s;\n}", .size = 447 } };
static const z_t58_t _zag1651[] = {{ .data = "@win_sep", .size = 8 }};

static const z_t6098_t _zag1652 = { { .data = "win_sep", .size = 7 }, { .length = 1, .data = _zag1651 }, { .length = 0, .data = NULL }, { .data = "static int z_win_sep(char c) {\n    return c == '\\\\' || c == '/';\n}", .size = 66 } };
